sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float tiles;
uniform float randOffset;
uniform float randRotation;
uniform float randScale;
uniform float baseScale;
uniform float seed;
uniform float animate;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 hash22(float2 p) {
    return float2(hash21(p), hash21(p + float2(17.31, 5.17)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float n = max(floor(tiles + 0.5), 1.0);
    float2 uv = coord / size * n;
    float2 cell = floor(uv);
    float2 f = fract(uv) - 0.5;
    float2 r = hash22(cell + seed * 3.1);
    float t = time * animate;
    float2 off = (float2(sin(t + r.x * 6.28), cos(t * 0.8 + r.y * 6.28)) * 0.5 + (r - 0.5)) * randOffset;
    float rot = (r.x - 0.5) * 2.0 * radians(randRotation);
    float sc = baseScale * (1.0 + (r.y - 0.5) * 2.0 * randScale);
    float2 q = rot2(f - off, -rot) / sc + 0.5;
    float inside = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
    return fin(c, texT(q * size) * inside, opacity);
}
